// Package snapshot saves the store to a JSON file and loads it back, so the server keeps its data across restarts. The
// file carries a version; files written by older versions of Tally are migrated when they are loaded.
package snapshot

import (
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"time"

	"example.com/tally/internal/money"
	"example.com/tally/internal/store"
)

// Version is the version Save writes.
const Version = 3

// ErrUnsupportedVersion is returned for a file of a version Load cannot read.
var ErrUnsupportedVersion = errors.New("unsupported snapshot version")

type fileV3 struct {
	Version int         `json:"version"`
	SavedAt time.Time   `json:"saved_at"`
	State   store.State `json:"state"`
}

type fileV2 struct {
	Version int         `json:"version"`
	SavedAt time.Time   `json:"saved_at"`
	State   store.State `json:"state"`
}

// Save writes everything in st to path. The file at path is either the previous snapshot or the whole new one.
func Save(st *store.Store, path string, now time.Time) error {
	return writeSnapshot(path, fileV3{Version: Version, SavedAt: now.UTC(), State: st.Export()})
}

func writeSnapshot(path string, f fileV3) error {
	b, err := json.MarshalIndent(f, "", "  ")
	if err != nil {
		return err
	}
	return writeAtomic(path, append(b, '\n'))
}

// writeAtomic writes data to a temporary file in the folder of path, then renames it over path. A failed write leaves no
// temporary file behind.
func writeAtomic(path string, data []byte) (err error) {
	f, err := os.CreateTemp(filepath.Dir(path), filepath.Base(path)+".*.tmp")
	if err != nil {
		return err
	}
	defer func() {
		if err != nil {
			_ = os.Remove(f.Name())
		}
	}()
	if _, err = f.Write(data); err != nil {
		_ = f.Close()
		return err
	}
	if err = f.Sync(); err != nil {
		_ = f.Close()
		return err
	}
	if err = f.Close(); err != nil {
		return err
	}
	return os.Rename(f.Name(), path)
}

// Load reads a snapshot written by Save, or by an older version of Tally, and returns a store holding it.
func Load(path string) (*store.Store, error) {
	b, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	st, _, err := decode(path, b)
	if err != nil {
		return nil, err
	}
	return store.FromState(st)
}

// Upgrade rewrites a snapshot of an older version as version 3. The original is first copied byte for byte to
// "<path>.v<old version>.bak". A version 3 file is left alone, and a file of a newer version fails with ErrUnsupportedVersion
// without being touched.
func Upgrade(path string) error {
	b, err := os.ReadFile(path)
	if err != nil {
		return err
	}
	st, v, err := decode(path, b)
	if err != nil {
		return err
	}
	if v == Version {
		return nil
	}
	s, err := store.FromState(st) // refuse a file that will not load before anything is written
	if err != nil {
		return fmt.Errorf("snapshot %s: %w", path, err)
	}
	if err := writeAtomic(fmt.Sprintf("%s.v%d.bak", path, v), b); err != nil {
		return err
	}
	return writeSnapshot(path, fileV3{Version: Version, SavedAt: time.Now().UTC(), State: s.Export()})
}

// decode reads the contents b of the snapshot at path, of any version Load can read, and returns its state and version.
func decode(path string, b []byte) (store.State, int, error) {
	var head struct {
		Version int `json:"version"`
	}
	if err := json.Unmarshal(b, &head); err != nil {
		return store.State{}, 0, fmt.Errorf("snapshot %s: %w", path, err)
	}
	switch head.Version {
	case 1:
		st, err := migrateV1(b)
		if err != nil {
			return store.State{}, 0, fmt.Errorf("snapshot %s: version 1: %w", path, err)
		}
		numberInvoices(&st)
		return st, 1, nil
	case 2:
		var f fileV2
		if err := json.Unmarshal(b, &f); err != nil {
			return store.State{}, 0, fmt.Errorf("snapshot %s: %w", path, err)
		}
		numberInvoices(&f.State)
		return f.State, 2, nil
	case 3:
		var f fileV3
		if err := json.Unmarshal(b, &f); err != nil {
			return store.State{}, 0, fmt.Errorf("snapshot %s: %w", path, err)
		}
		return f.State, 3, nil
	}
	return store.State{}, head.Version, fmt.Errorf("snapshot %s: %w %d", path, ErrUnsupportedVersion, head.Version)
}

// numberInvoices gives the invoices of a snapshot that predates invoice numbers their numbers: per organization, in creation
// order (created_at, then ID). Each organization's next number then follows its highest.
func numberInvoices(st *store.State) {
	sort.Slice(st.Invoices, func(i, j int) bool {
		a, b := st.Invoices[i], st.Invoices[j]
		if !a.CreatedAt.Equal(b.CreatedAt) {
			return a.CreatedAt.Before(b.CreatedAt)
		}
		return a.ID < b.ID
	})
	st.InvoiceNext = map[string]int{}
	for i := range st.Invoices {
		inv := &st.Invoices[i]
		n := st.InvoiceNext[inv.OrgID] + 1
		st.InvoiceNext[inv.OrgID] = n
		inv.Number = store.FormatInvoiceNumber(n)
	}
}

// Version 1 (Tally 0.x) kept the state at the top level. Organizations had no plan or time zone, customers had a
// full_name, and plans had a price in US cents (price_cents) and were all licensed.
type fileV1 struct {
	Seq           int                  `json:"seq"`
	Orgs          []orgV1              `json:"orgs"`
	Users         []store.User         `json:"users"`
	Members       []store.Member       `json:"members"`
	APIKeys       []store.APIKey       `json:"api_keys"`
	Customers     []customerV1         `json:"customers"`
	Plans         []planV1             `json:"plans"`
	Subscriptions []store.Subscription `json:"subscriptions"`
	Invoices      []store.Invoice      `json:"invoices"`
	Payments      []store.Payment      `json:"payments"`
}

type orgV1 struct {
	ID        string    `json:"id"`
	Name      string    `json:"name"`
	TaxRateBP int       `json:"tax_rate_bp"`
	CreatedAt time.Time `json:"created_at"`
}

type customerV1 struct {
	ID        string    `json:"id"`
	OrgID     string    `json:"org_id"`
	FullName  string    `json:"full_name"`
	Email     string    `json:"email"`
	CreatedAt time.Time `json:"created_at"`
}

type planV1 struct {
	ID         string         `json:"id"`
	OrgID      string         `json:"org_id"`
	Name       string         `json:"name"`
	PriceCents int64          `json:"price_cents"`
	Interval   store.Interval `json:"interval"`
	TrialDays  int            `json:"trial_days"`
	CreatedAt  time.Time      `json:"created_at"`
}

func migrateV1(b []byte) (store.State, error) {
	var f fileV1
	if err := json.Unmarshal(b, &f); err != nil {
		return store.State{}, err
	}
	st := store.State{Seq: f.Seq, Users: f.Users, Members: f.Members, APIKeys: f.APIKeys, Subscriptions: f.Subscriptions, Invoices: f.Invoices, Payments: f.Payments}
	for _, o := range f.Orgs {
		st.Orgs = append(st.Orgs, store.Org{ID: o.ID, Name: o.Name, Plan: store.OrgFree, TimeZone: "UTC", TaxRateBP: o.TaxRateBP, CreatedAt: o.CreatedAt})
	}
	for _, c := range f.Customers {
		st.Customers = append(st.Customers, store.Customer{ID: c.ID, OrgID: c.OrgID, Name: c.FullName, Email: c.Email, CreatedAt: c.CreatedAt})
	}
	for _, p := range f.Plans {
		st.Plans = append(st.Plans, store.Plan{ID: p.ID, OrgID: p.OrgID, Name: p.Name, Currency: money.USD, UnitAmount: p.PriceCents, Interval: p.Interval,
			UsageType: store.Licensed, TrialDays: p.TrialDays, Active: true, CreatedAt: p.CreatedAt})
	}
	return st, nil
}

