// sampleStore returns a store with two organizations and invoices in both; the first organization's invoices are created
// later than the second's, and the second one's ID is higher, so created_at and ID order differ.
func sampleStore(t *testing.T) (*store.Store, store.Invoice, store.Invoice) {
	t.Helper()
	now := time.Date(2026, 2, 1, 12, 0, 0, 0, time.UTC)
	st := store.New()
	o, _ := st.CreateOrg("A", store.OrgTeam, "Europe/Berlin", 1900, now)
	c, _ := st.CreateCustomer(o.ID, "Jane", "jane@example.com", now)
	line := []store.Line{{Description: "x", Quantity: 2, UnitAmount: 150}}
	first, err := st.CreateInvoice(store.Invoice{OrgID: o.ID, CustomerID: c.ID, Currency: money.EUR, Lines: line}, now.Add(time.Hour))
	if err != nil {
		t.Fatal(err)
	}
	second, err := st.CreateInvoice(store.Invoice{OrgID: o.ID, CustomerID: c.ID, Currency: money.EUR, Lines: line}, now)
	if err != nil {
		t.Fatal(err)
	}
	return st, first, second
}

func TestSaveWritesVersion3WithNumbers(t *testing.T) {
	now := time.Date(2026, 2, 1, 12, 0, 0, 0, time.UTC)
	st := store.New()
	a, _ := st.CreateOrg("A", store.OrgTeam, "UTC", 0, now)
	b, _ := st.CreateOrg("B", store.OrgTeam, "UTC", 0, now)
	ca, _ := st.CreateCustomer(a.ID, "Ann", "ann@example.com", now)
	cb, _ := st.CreateCustomer(b.ID, "Bob", "bob@example.com", now)
	line := []store.Line{{Description: "x", Quantity: 1, UnitAmount: 100}}
	for range 2 {
		if _, err := st.CreateInvoice(store.Invoice{OrgID: a.ID, CustomerID: ca.ID, Currency: money.EUR, Lines: line}, now); err != nil {
			t.Fatal(err)
		}
	}
	if _, err := st.CreateInvoice(store.Invoice{OrgID: b.ID, CustomerID: cb.ID, Currency: money.EUR, Lines: line}, now); err != nil {
		t.Fatal(err)
	}

	path := filepath.Join(t.TempDir(), "tally.json")
	if err := Save(st, path, now); err != nil {
		t.Fatal(err)
	}
	if v := fileVersion(t, path); v != 3 {
		t.Fatalf("version = %d, want 3", v)
	}
	got, err := Load(path)
	if err != nil {
		t.Fatal(err)
	}
	if n := invoiceNumbers(t, got, a.ID); len(n) != 2 || !reflect.DeepEqual(sortedValues(n), []string{"INV-000001", "INV-000002"}) {
		t.Fatalf("numbers of A = %v", n)
	}
	if n := invoiceNumbers(t, got, b.ID); !reflect.DeepEqual(sortedValues(n), []string{"INV-000001"}) {
		t.Fatalf("numbers of B = %v", n)
	}
	inv, err := got.CreateInvoice(store.Invoice{OrgID: a.ID, CustomerID: ca.ID, Currency: money.EUR, Lines: line}, now)
	if err != nil || inv.Number != "INV-000003" {
		t.Fatalf("the next invoice of A = %+v, %v", inv, err)
	}
}

func sortedValues(m map[string]string) []string {
	out := []string{}
	for _, v := range m {
		out = append(out, v)
	}
	sort.Strings(out)
	return out
}

func TestLoadVersion2NumbersInvoicesInCreationOrder(t *testing.T) {
	st, first, second := sampleStore(t)
	path := filepath.Join(t.TempDir(), "tally.json")
	writeVersion2(t, st, path)

	got, err := Load(path)
	if err != nil {
		t.Fatal(err)
	}
	numbers := invoiceNumbers(t, got, first.OrgID)
	if numbers[second.ID] != "INV-000001" || numbers[first.ID] != "INV-000002" {
		t.Fatalf("numbers = %v; the invoice created first (by created_at) should be INV-000001", numbers)
	}
	next, err := got.CreateInvoice(store.Invoice{OrgID: first.OrgID, CustomerID: first.CustomerID, Currency: money.EUR, Lines: first.Lines}, time.Now())
	if err != nil || next.Number != "INV-000003" {
		t.Fatalf("the next invoice = %+v, %v", next, err)
	}
}

func TestSaveLeavesNoTemporaryFile(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "tally.json")
	st := store.New()
	for range 2 {
		if err := Save(st, path, time.Now()); err != nil {
			t.Fatal(err)
		}
	}
	entries, err := os.ReadDir(dir)
	if err != nil {
		t.Fatal(err)
	}
	if len(entries) != 1 || entries[0].Name() != "tally.json" {
		t.Fatalf("the folder holds %v after saving; want only tally.json", entries)
	}
	if err := Save(st, filepath.Join(dir, "missing", "tally.json"), time.Now()); err == nil {
		t.Fatal("saving into a missing folder succeeded")
	}
	if entries, _ := os.ReadDir(dir); len(entries) != 1 {
		t.Fatalf("a failed save left %v behind", entries)
	}
}

func TestUpgradeVersion1(t *testing.T) {
	orig, err := os.ReadFile(filepath.Join("testdata", "v1.json"))
	if err != nil {
		t.Fatal(err)
	}
	path := filepath.Join(t.TempDir(), "tally.json")
	if err := os.WriteFile(path, orig, 0o600); err != nil {
		t.Fatal(err)
	}
	if err := Upgrade(path); err != nil {
		t.Fatal(err)
	}
	if bak, err := os.ReadFile(path + ".v1.bak"); err != nil || !bytes.Equal(bak, orig) {
		t.Fatalf("the backup differs from the original: %v", err)
	}
	if v := fileVersion(t, path); v != 3 {
		t.Fatalf("version = %d, want 3", v)
	}
	got, err := Load(path)
	if err != nil {
		t.Fatal(err)
	}
	const org = "org_000001"
