}

func TestSaveLeavesNoTemporaryFile(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "tally.json")
	st := store.New()
	for range 2 {
		if err := Save(st, path, time.Now()); err != nil {
			t.Fatal(err)
		}
	}
	entries, err := os.ReadDir(dir)
	if err != nil {
		t.Fatal(err)
	}
	if len(entries) != 1 || entries[0].Name() != "tally.json" {
		t.Fatalf("the folder holds %v after saving; want only tally.json", entries)
	}
	if err := Save(st, filepath.Join(dir, "missing", "tally.json"), time.Now()); err == nil {
		t.Fatal("saving into a missing folder succeeded")
	}
	if entries, _ := os.ReadDir(dir); len(entries) != 1 {
		t.Fatalf("a failed save left %v behind", entries)
	}
}

func TestUpgradeVersion1(t *testing.T) {
	orig, err := os.ReadFile(filepath.Join("testdata", "v1.json"))
	if err != nil {
		t.Fatal(err)
	}
	path := filepath.Join(t.TempDir(), "tally.json")
	if err := os.WriteFile(path, orig, 0o600); err != nil {
		t.Fatal(err)
	}
	if err := Upgrade(path); err != nil {
		t.Fatal(err)
	}
	if bak, err := os.ReadFile(path + ".v1.bak"); err != nil || !bytes.Equal(bak, orig) {
		t.Fatalf("the backup differs from the original: %v", err)
	}
	if v := fileVersion(t, path); v != 3 {
		t.Fatalf("version = %d, want 3", v)
	}
	got, err := Load(path)
	if err != nil {
		t.Fatal(err)
	}
	const org = "org_000001"
	count := len(got.ListInvoices(org, store.InvoiceFilter{}))
	if inv, ok := got.Invoice(org, "in_000007"); !ok || inv.Number == "" {
		t.Fatalf("invoice in_000007 = %+v", inv)
	}
	next, err := got.CreateInvoice(store.Invoice{OrgID: org, CustomerID: "cus_000004", Currency: money.USD, Lines: []store.Line{{Description: "x", Quantity: 1, UnitAmount: 1}}}, time.Now())
	if err != nil || next.Number != store.FormatInvoiceNumber(count+1) {
		t.Fatalf("the next invoice = %+v, %v; want %s after %d invoices", next, err, store.FormatInvoiceNumber(count+1), count)
	}

	// Upgrading a version 3 file again changes nothing.
	after, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	if err := Upgrade(path); err != nil {
		t.Fatal(err)
	}
	if again, _ := os.ReadFile(path); !bytes.Equal(again, after) {
		t.Fatal("upgrading a version 3 file changed it")
	}
}

func TestUpgradeVersion2(t *testing.T) {
	st, _, _ := sampleStore(t)
	path := filepath.Join(t.TempDir(), "tally.json")
	orig := writeVersion2(t, st, path)

	if err := Upgrade(path); err != nil {
		t.Fatal(err)
	}
	if bak, err := os.ReadFile(path + ".v2.bak"); err != nil || !bytes.Equal(bak, orig) {
		t.Fatalf("the backup differs from the original: %v", err)
	}
	if v := fileVersion(t, path); v != 3 {
		t.Fatalf("version = %d, want 3", v)
	}
	got, err := Load(path)
	if err != nil {
		t.Fatal(err)
	}
	if n := invoiceNumbers(t, got, st.Export().Orgs[0].ID); !reflect.DeepEqual(sortedValues(n), []string{"INV-000001", "INV-000002"}) {
		t.Fatalf("numbers = %v", n)
	}
}

func TestUpgradeLeavesVersion3AloneWithoutBackup(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "tally.json")
	if err := Save(store.New(), path, time.Now()); err != nil {
		t.Fatal(err)
	}
	before, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	if err := Upgrade(path); err != nil {
		t.Fatal(err)
	}
	if after, _ := os.ReadFile(path); !bytes.Equal(after, before) {
		t.Fatal("upgrading a version 3 file changed it")
	}
	if entries, _ := os.ReadDir(dir); len(entries) != 1 {
		t.Fatalf("the folder holds %v; a version 3 file needs no backup", entries)
	}
}

func TestUpgradeRefusesNewerVersions(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "future.json")
	future := []byte(`{"version": 4, "state": {}}`)
	if err := os.WriteFile(path, future, 0o600); err != nil {
		t.Fatal(err)
	}
	if err := Upgrade(path); !errors.Is(err, ErrUnsupportedVersion) {
		t.Fatalf("err = %v", err)
	}
	if after, _ := os.ReadFile(path); !bytes.Equal(after, future) {
		t.Fatal("a newer file was changed")
	}
	if entries, _ := os.ReadDir(dir); len(entries) != 1 {
		t.Fatalf("the folder holds %v; a refused upgrade writes nothing", entries)
	}
}

