246	// CreateInvoice stores an invoice for one of the organization's customers, with the organization's tax rate. It is open.
247	func (s *Store) CreateInvoice(inv Invoice, now time.Time) (Invoice, error) {
248		if !inv.Currency.Valid() {
249			return Invoice{}, invalid("unknown currency %q", inv.Currency)
250		}
251		if inv.DiscountPercent < 0 || inv.DiscountPercent > 100 {
252			return Invoice{}, invalid("the discount is 0 to 100 percent")
253		}
254		for _, l := range inv.Lines {
255			if l.Quantity <= 0 {
256				return Invoice{}, invalid("a line needs a positive quantity")
257			}
258		}
259		s.mu.Lock()
260		defer s.mu.Unlock()
261		org, ok := s.orgs[inv.OrgID]
262		if !ok {
263			return Invoice{}, ErrNotFound
264		}
265		c, ok := s.customers[inv.CustomerID]
266		if !ok {
267			return Invoice{}, ErrNotFound
268		}
269		if c.OrgID != inv.OrgID {
270			return Invoice{}, ErrCustomerOrgMismatch
271		}
272		inv.ID = s.newID("in")
273		n := max(s.invoiceNext[inv.OrgID], 1)
274		inv.Number = FormatInvoiceNumber(n)
275		s.invoiceNext[inv.OrgID] = n + 1
276		inv.TaxRateBP = org.TaxRateBP
277		inv.Status = InvoiceOpen
278		inv.CreatedAt = now.UTC()
279		inv.PaidAt, inv.VoidedAt = nil, nil
280		inv = copyInvoice(inv)
281		s.invoices[inv.ID] = inv
282		return copyInvoice(inv), nil
283	}
